import{_ as o,o as e,c as s,a2 as i}from"./chunks/framework.DA69LXMH.js";const u=JSON.parse('{"title":"Solução de Problemas (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"suporte/solucao-problemas.md","filePath":"suporte/solucao-problemas.md"}'),r={name:"suporte/solucao-problemas.md"};function c(t,a,n,l,d,m){return e(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="solucao-de-problemas-faq" tabindex="-1">Solução de Problemas (FAQ) <a class="header-anchor" href="#solucao-de-problemas-faq" aria-label="Permalink to &quot;Solução de Problemas (FAQ)&quot;">​</a></h1><p>Aqui estão as respostas e soluções para as dúvidas e situações mais comuns no uso do EchoBot.</p><hr><h3 id="❓-o-echobot-nao-esta-reconhecendo-minha-voz-microfone" tabindex="-1">❓ O EchoBot não está reconhecendo minha voz / microfone <a class="header-anchor" href="#❓-o-echobot-nao-esta-reconhecendo-minha-voz-microfone" aria-label="Permalink to &quot;❓ O EchoBot não está reconhecendo minha voz / microfone&quot;">​</a></h3><ol><li>Vá em <strong>Configurações do Windows &gt; Privacidade e Segurança &gt; Microfone</strong> e certifique-se de que o acesso ao microfone está ativado para aplicativos da área de trabalho.</li><li>No menu de configurações do EchoBot, teste se o dispositivo selecionado corresponde à sua entrada principal de áudio.</li><li>Se estiver usando o modo CPU, aumente a sensibilidade do VAD ou selecione o modelo Whisper <em>Tiny</em> para diminuir a latência.</li></ol><hr><h3 id="❓-como-habilitar-a-aceleracao-por-gpu-cuda" tabindex="-1">❓ Como habilitar a aceleração por GPU (CUDA)? <a class="header-anchor" href="#❓-como-habilitar-a-aceleracao-por-gpu-cuda" aria-label="Permalink to &quot;❓ Como habilitar a aceleração por GPU (CUDA)?&quot;">​</a></h3><ol><li>Certifique-se de ter uma placa de vídeo NVIDIA compatível.</li><li>Baixe e instale os drivers mais recentes da sua GPU via GeForce Experience ou site oficial da NVIDIA.</li><li>Nas configurações do EchoBot, selecione o dispositivo <code>cuda</code> para ativar o processamento paralelo.</li></ol><hr><h3 id="❓-onde-ficam-salvas-as-minhas-campanhas-e-gravacoes" tabindex="-1">❓ Onde ficam salvas as minhas campanhas e gravações? <a class="header-anchor" href="#❓-onde-ficam-salvas-as-minhas-campanhas-e-gravacoes" aria-label="Permalink to &quot;❓ Onde ficam salvas as minhas campanhas e gravações?&quot;">​</a></h3><p>Todos os dados das suas campanhas, logs e configurações são salvos localmente na pasta <code>data/</code> do seu diretório de instalação do EchoBot, garantindo total privacidade e facilidade de backup.</p>',11)])])}const p=o(r,[["render",c]]);export{u as __pageData,p as default};
